<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount } from 'vue'
import logo from '~/assets/logo.png'
import heroBg from '~/assets/20260415_124559.jpg'
import { z } from 'zod'
const menuOpen = ref(false)
const submitted = ref(false)
const formErrors = ref<Record<string, string>>({})
const amenityIndex = ref(0)
const amenities = [
  { title: 'Conference centre', image: 'https://images.unsplash.com/photo-1505373877841-8d25f7d46678?auto=format&fit=crop&w=900&q=85' },
  { title: 'ICT hub', image: 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=900&q=85' },
  { title: 'Education centres', image: 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=900&q=85' },
  { title: 'Hospitals', image: 'https://images.unsplash.com/photo-1587351021759-3e566b6af7cc?auto=format&fit=crop&w=900&q=85' }
]
const interestSchema = z.object({ name: z.string().trim().min(2, 'Please enter your name'), email: z.string().trim().email('Enter a valid email address'), phone: z.string().trim().min(7, 'Enter a valid international phone number').regex(/^\+?[0-9 ()-]{7,20}$/, 'Use an international number, e.g. +254 700 000 000'), message: z.string().trim().min(10, 'Please tell us how we can help') })
const nextAmenity = (direction: number) => { amenityIndex.value = (amenityIndex.value + direction + amenities.length) % amenities.length }
const submitInterest = (event: Event) => { formErrors.value = {}; submitted.value = false; const data = Object.fromEntries(new FormData(event.target as HTMLFormElement)); const result = interestSchema.safeParse(data); if (!result.success) { for (const issue of result.error.issues) formErrors.value[issue.path[0] as string] = issue.message; return } submitted.value = true; (event.target as HTMLFormElement).reset() }
const year = new Date().getFullYear()
const offers = [
  { category: 'Changai Valley', title: '0.25 Acre Residential Plots', description: 'Scenic residential plots in a controlled gated community environment, ideal for building a first or second home.', price: 'From 4.5 Million', bullets: ['Controlled gated community development', 'Graded Roads', 'Street lighting', 'Power and Water Supply connection close by', 'Clean Title'] },
  { category: 'Changai Valley', title: '0.5 Acre Residential Plots', description: 'Scenic residential plots in a controlled gated community environment, ideal for building a first or second home.', price: 'From 8.5 Million', bullets: ['Controlled gated community development', 'Graded Roads', 'Street lighting', 'Power and Water Supply close by', 'Clean Title'] },
  { category: 'Light Industrial', title: '0.25 Acre Industrial Plots', description: '0.25 acre Industrial Plots located at the edge of Changai Valley with multiple access routes.', price: 'From 6 Million', bullets: ['Controlled environment within the larger scheme', 'Graded Roads', 'Power and Water Supply connection close by', 'Street Lighting', 'Clean Title'] },
  { category: 'Agricultural', title: '2.5 Acre Agricultural Plots', description: 'Scenic agricultural plots located at the edge of the valley, ideal for building a farm house and practising subsistence farming.', price: 'From KES. 8.5 Million per Acre', bullets: ['Controlled gated community development', 'Graded Roads', 'Street lighting', 'Power and Water Supply close by', 'Clean Title'] },
]
const scrollTo = (id: string) => { menuOpen.value = false; document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' }) }
const activeSection = ref('home')
const onScroll = () => { const ids = ['home', 'gallery', 'offers', 'location', 'contact']; let current = 'home'; for (const id of ids) { const el = document.getElementById(id); if (el && el.getBoundingClientRect().top <= 150) current = id } activeSection.value = current }
onMounted(() => { window.addEventListener('scroll', onScroll, { passive: true }); onScroll() })
onBeforeUnmount(() => window.removeEventListener('scroll', onScroll))
</script>
<template>
<div class="site"><header class="header"><div class="header-inner"><a class="brand" href="#home" @click.prevent="scrollTo('home')"><img class="mark logo" :src="logo" alt="Changai Garden City logo"><span><b>changai</b><small>GARDEN CITY</small></span></a><button class="menu" @click="menuOpen=!menuOpen">☰</button><nav :class="{open:menuOpen}"><a href="#home" :class="{active:activeSection==='home'}" @click.prevent="scrollTo('home')">HOME</a><a href="#gallery" :class="{active:activeSection==='gallery'}" @click.prevent="scrollTo('gallery')">PROJECT AMENITIES</a><a href="#offers" :class="{active:activeSection==='offers'}" @click.prevent="scrollTo('offers')">OFFERS</a><a href="#location" :class="{active:activeSection==='location'}" @click.prevent="scrollTo('location')">LOCATION</a><a href="#contact" :class="{active:activeSection==='contact'}" @click.prevent="scrollTo('contact')">CONTACT</a><span class="socials"><a href="#" aria-label="Facebook" title="Facebook"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M22 12a10 10 0 1 0-11.6 9.9v-7H7.9V12h2.5V9.8c0-2.5 1.5-3.9 3.8-3.9 1.1 0 2.2.2 2.2.2v2.5h-1.3c-1.2 0-1.6.8-1.6 1.6V12h2.8l-.4 2.9h-2.4v7A10 10 0 0 0 22 12z"/></svg></a><a href="#" aria-label="Instagram" title="Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2.5" y="2.5" width="19" height="19" rx="5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4.2" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="17.2" cy="6.8" r="1.4" fill="currentColor"/></svg></a><a href="#" aria-label="X" title="X"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M18.9 2H22l-6.8 7.8L23.3 22h-6.3l-4.9-6.4L6.4 22H3.3l7.3-8.3L1.6 2H8l4.4 5.9L17.8 2zm-1.1 18h1.7L7.1 3.7H5.3L17.8 20z"/></svg></a><a href="#" aria-label="YouTube" title="YouTube"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="5" width="20" height="14" rx="4" fill="none" stroke="currentColor" stroke-width="2"/><path d="M10 9.5v5l4.5-2.5z" fill="currentColor"/></svg></a></span></nav></div></header>
<main><section id="home" class="hero" :style="{ backgroundImage: `linear-gradient(90deg,rgba(255,255,255,.46),rgba(255,255,255,.29)), url('${heroBg}')` }"><div class="hero-copy"><h1>Living meets<br><em>nature.</em></h1><p>Changai Garden City is a 200-acre master-planned mixed use development located in the heart of Makuyu, Murang’a County.</p><p>The development is set against a backdrop of lush, green countryside and offers a rare opportunity to own land in an area that is both beautiful, well-planned and ...</p><div class="hero-actions"><a class="button primary" href="#contact">Schedule A Visit ↗</a><a class="button outline" href="#offers">Download Brochure ↓</a></div></div><div class="hero-stat"><strong>200</strong><span>acres<br>of possibility</span></div></section>
<section id="gallery" class="amenities section section-with-hero-bg"><div class="section-title"><h2>Project<br><em>amenities.</em></h2><p class="amenity-intro">Changai Garden City is planned as a connected, mixed-use community where essential services and everyday life are close at hand.</p></div><div class="amenity-carousel"><button class="carousel-arrow" aria-label="Previous amenity" @click="nextAmenity(-1)">←</button><div class="amenity-track"><article v-for="(amenity, index) in amenities" v-show="index === amenityIndex" :key="amenity.title"><img :src="amenity.image" :alt="amenity.title"><div><span>0{{index + 1}}</span><h3>{{amenity.title}}</h3></div></article></div><button class="carousel-arrow" aria-label="Next amenity" @click="nextAmenity(1)">→</button><div class="carousel-dots"><button v-for="(amenity, index) in amenities" :key="amenity.title" :class="{active: index === amenityIndex}" :aria-label="`Show ${amenity.title}`" @click="amenityIndex = index"></button></div></div></section>
<section id="offers" class="parcels section section-with-hero-bg"><div class="section-top"><div><p class="eyebrow">A place to put down roots</p><h2>Parcels with<br><em>possibility.</em></h2></div><p>Choose a plot that fits the way you want to live, grow and build.</p></div><div class="parcel-grid"><article><b>01</b><h3>Residential</h3><p>Quarter acre plots for a first or second home in a beautiful, thoughtfully planned community.</p><ul><li>Changai Valley (Phase 1)</li><li>Changai Ridge</li><li>Changai Gardens</li></ul></article><article><b>02</b><h3>Agricultural</h3><p>Room for a farmhouse and subsistence farming.</p></article><article><b>03</b><h3>Light Industrial</h3><p>Purposeful space for enterprise and industry.</p></article><article><b>04</b><h3>Commercial</h3><p>Well-positioned space for retail, offices and everyday services.</p></article><article><b>05</b><h3>Hospitality</h3><p>Room for hotels, lodges and destination experiences.</p></article><article><b>06</b><h3>Educational</h3><p>Dedicated space for schools and learning institutions.</p></article></div></section>
<section class="offers section section-with-hero-bg"><div class="offers-heading"><h2>Find Your Changai <em>Valley Offers.</em></h2></div><div class="offer-grid"><article v-for="offer in offers" :key="offer.title" class="offer-card"><p v-if="offer.category" class="category">{{offer.category}}</p><h3>{{offer.title}}</h3><p class="description">{{offer.description}}</p><p class="price">- Price: <strong>{{ offer.price }}</strong></p><p class="infrastructure">Infrastructure:</p><ul><li v-for="bullet in offer.bullets" :key="bullet">{{bullet}}</li></ul><div class="actions"><a class="status" href="#contact">Status: Available</a><a class="book" href="#contact">Book Your Plot</a></div></article></div></section>
<section id="location" class="location section section-with-hero-bg"><div><p class="eyebrow">Location / map</p><h2>Connected to<br><em>everything.</em></h2><p>Find Changai Garden City at the centre of a growing network of towns, services and transport links.</p><a class="button primary" href="#contact">Get directions ↗</a></div><div class="map"><span class="pin">●</span><strong>Changai Garden City</strong><small>Phase 1</small><i>Makuyu Centre</i><i>Kenol Town</i><b>N</b></div></section>
<section id="contact" class="contact section section-with-hero-bg"><div><p class="eyebrow">Customer form</p><h2>Register<br><em>your interest.</em></h2><p>Fill in the form to register your interest.</p><address><strong>Changai Garden City Ltd</strong><br>Call us on <a href="tel:07********">07********</a><br>Email us on <a href="mailto:sales@changaigardencity.com">sales@changaigardencity.com</a><br><br><strong>Find us on</strong><br>Off Njathaini Road<br>Nairobi County</address></div><form @submit.prevent="submitInterest"><div class="form-row"><label>Name:<input name="name" autocomplete="name" placeholder="Your name"><small v-if="formErrors.name">{{formErrors.name}}</small></label><label>Email:<input name="email" type="email" autocomplete="email" placeholder="you@example.com"><small v-if="formErrors.email">{{formErrors.email}}</small></label></div><div class="form-row"><label>Phone:<input name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="+254 700 000 000"><small v-if="formErrors.phone">{{formErrors.phone}}</small></label><label>Message:<textarea name="message" rows="3" placeholder="How can we help?"></textarea><small v-if="formErrors.message">{{formErrors.message}}</small></label></div><button class="button primary" type="submit">Submit ↗</button><p v-if="submitted" class="success">Thank you — we’ll be in touch shortly.</p></form></section></main>
<footer><a class="brand" href="#home"><img class="mark logo" :src="logo" alt="Changai Garden City logo"><span><b>changai</b><small>GARDEN CITY</small></span></a><p>Living meets nature.</p><span>© {{ year }} Changai Garden City</span></footer></div>
</template>
